 async function prepare(signal){castleGoals.clear();for(let home=0;home<2;home++){const authored=castleGoal(null,home,false),pad=world.pads[home],heart=world.castleHearts[home].core.getWorldPosition(new T.Vector3());const alternatives=navigation.nodes.filter(n=>n.y>pad.y+5&&Math.hypot(n.x-pad.x,n.z-pad.z)<175).sort((a,b)=>distance(a,heart)-distance(b,heart));const choices=authored?[authored]:[];for(const p of alternatives){if(choices.every(q=>distance(p,q)>15))choices.push(p);if(choices.length>=4)break;}let selected=null;for(const goal of choices){const route=await navigation.path(pad,{...goal,radius:3},{signal,maxMs:1000});if(route.reachable){selected=goal;break;}}castleGoals.set(home,selected);}}
