 function dodge(actor,projectiles,time){if(time<(actor.dodgeAt??0)||actor.state.flight||!actor.state.grounded)return null;actor.dodgeAt=time+.16;for(const p of projectiles||[]){if(p.active===false||p.team===actor.team)continue;const pos=p.position||p,vel=p.velocity||p,vx=vel.vx??vel.x??0,vz=vel.vz??vel.z??0,speed2=vx*vx+vz*vz;if(!speed2||Math.abs((pos.y??0)-actor.state.y)>4)continue;const dx=actor.state.x-pos.x,dz=actor.state.z-pos.z,t=(dx*vx+dz*vz)/speed2;if(t<0||t>.65||Math.hypot(dx-vx*t,dz-vz*t)>1.8)continue;const speed=Math.sqrt(speed2),sign=(actor.id%2?1:-1);for(const side of [sign,-sign]){const x=-vz/speed*side,z=vx/speed*side;if(navigation.safeStep(actor.state,x,z,1.25)){actor.evades++;actor.evadeUntil=time+.23;actor.evadeInput={x,z};return actor.evadeInput;}}}return null;}
